insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('welldata', 'beginner', 'module', 'm01-well-data-and-the-registry', 1, 'Why is Well Data Manager the root of the NextGen geoscience path, with its Associate certificate required before the other courses?', '["Every downstream workflow consumes well curves, so learners must be able to receive and QC data before they interpret it","It is the shortest course, so it serves as a quick orientation","The other courses reuse its user interface components","Regulations require a data management certificate before any interpretation work"]'::jsonb, 0, 'Petrophysics, correlation, synthetics, mapping and volumetrics all build on well curves, so the path teaches receiving and checking data before interpreting it.'),
  ('welldata', 'beginner', 'module', 'm01-well-data-and-the-registry', 2, 'Why is a data error that does not crash any software more dangerous than one that does?', '["Crashes corrupt the database, while silent errors only affect displays","A silent error produces plausible-looking numbers and travels downstream, surfacing only much later and far from where it entered","Non-crashing errors are always smaller in magnitude","Software vendors patch crashing errors faster"]'::jsonb, 1, 'The gap between where an error enters and where it is discovered is what makes it expensive; silent errors ride along in respectable-looking numbers.'),
  ('welldata', 'beginner', 'module', 'm01-well-data-and-the-registry', 3, 'A file records depth from 4900 to 5200 in feet. If an importer reads those values as metres, what happens?', '["The import fails because the depth column is not monotonic","The curves are unaffected because only the depth labels change","Every sample is positioned more than three kilometres too deep, with no error raised","The parser automatically detects the mistake from the STEP value"]'::jsonb, 2, '4900 ft is really about 1493.5 m; treating the numbers as metres silently places the well over three kilometres too deep while everything still plots.'),
  ('welldata', 'beginner', 'module', 'm01-well-data-and-the-registry', 4, 'A well is logged from 1500 to 1650 m at a 0.5 m step. How many depth samples does it hold?', '["300","301","299","151"]'::jsonb, 1, 'There are (1650 - 1500)/0.5 = 300 intervals, and the fence-post rule adds one: both end points carry a sample, giving 301.'),
  ('welldata', 'beginner', 'module', 'm01-well-data-and-the-registry', 5, 'wrapped_12.las logs from 1500 to 1580 m at a 0.5 m step. Its depth sample count is:', '["160","80","159","161"]'::jsonb, 3, '(1580 - 1500)/0.5 = 160 intervals, plus one for the fence-post rule, gives 161 samples.'),
  ('welldata', 'beginner', 'module', 'm01-well-data-and-the-registry', 6, 'A file logs from 1500 to 1600 m at a 0.5 m step. How many depth samples?', '["201","200","101","199"]'::jsonb, 0, '(1600 - 1500)/0.5 = 200 intervals, plus one, is 201 samples; this is the sample count of nullheavy_20.'),
  ('welldata', 'beginner', 'module', 'm01-well-data-and-the-registry', 7, 'What does the GR curve measure, and how does it behave across lithology?', '["Bulk density; it reads high in dense carbonates","Acoustic travel time; it reads high in slow formations","Natural radioactivity; it reads high in shale and low in clean sand","Hydrogen content; it reads high in gas zones"]'::jsonb, 2, 'Gamma ray responds to natural radioactivity, which concentrates in clays, so shale reads high and clean sand reads low.'),
  ('welldata', 'beginner', 'module', 'm01-well-data-and-the-registry', 8, 'In the metric teaching files, the DT curve is denominated in:', '["microseconds per foot","microseconds per metre","metres per second","milliseconds per metre"]'::jsonb, 1, 'The metric files carry DT in us/m; feet_20 is the file whose sonic arrives in us/ft and needs conversion.'),
  ('welldata', 'beginner', 'module', 'm01-well-data-and-the-registry', 9, 'basic_20''s GR curve spans 301 samples and 8 of them are null. How many samples enter its mean, and why?', '["301, because the null flag is a valid measurement","301, because nulls are replaced by zero before averaging","8, because only flagged samples are trusted","293, because statistics are computed over finite samples only"]'::jsonb, 3, 'Total minus nulls is 301 - 8 = 293 finite samples; means are computed over finite samples so the null flag never leaks into the arithmetic.'),
  ('welldata', 'beginner', 'module', 'm01-well-data-and-the-registry', 10, 'Which teaching file marks missing samples with -9999 instead of the common -999.25?', '["nullheavy_20.las","basic_20.las","quirks_20.las","wrapped_12.las"]'::jsonb, 0, 'nullheavy_20 declares NULL -9999; a reader that assumes -999.25 would treat every missing sample there as a real, very negative value.'),
  ('welldata', 'beginner', 'module', 'm01-well-data-and-the-registry', 11, 'Which teaching file is written in LAS version 1.2 with wrapped mode on?', '["feet_20.las","irregular_20.las","wrapped_12.las","basic_20.las"]'::jsonb, 2, 'wrapped_12 is the LAS 1.2 file whose depth steps span several physical lines; only a wrap-aware parser counts its 161 samples correctly.'),
  ('welldata', 'beginner', 'module', 'm01-well-data-and-the-registry', 12, 'A LAS header declares STEP as 0. By convention this means:', '["The file has exactly one depth sample","The depth sampling is irregular, so no single step applies","The step must be read from the first two data rows instead","The file is corrupt and should be rejected"]'::jsonb, 1, 'STEP 0 is the standard LAS way of declaring irregular sampling, as irregular_20 does; the average step can still look normal, which is why the declaration matters.'),
  ('welldata', 'beginner', 'module', 'm01-well-data-and-the-registry', 13, 'What is a dead curve?', '["A curve whose mean falls outside its physical range","A curve recorded by a decommissioned tool","A curve whose mnemonic is not recognised","A curve with no finite samples at all, every value being null"]'::jsonb, 3, 'A dead curve is null at every depth, like NPHI in nullheavy_20 with 201 null samples out of 201; it should never be published as data.'),
  ('welldata', 'beginner', 'module', 'm01-well-data-and-the-registry', 14, 'The four questions import QC answers, in the order this course teaches them, are:', '["Structure, units, sampling, completeness","Provenance, precision, plotting, publishing","Header, curves, depth, statistics","Version, vendor, velocity, validation"]'::jsonb, 0, 'Is the structure right, are the units right, is the sampling right, and is the data complete: every QC panel reading serves one of these four.'),
  ('welldata', 'beginner', 'module', 'm01-well-data-and-the-registry', 15, 'Why is publishing a bad curve to the shared well registry worse than keeping it in a local project file?', '["Registry storage is more expensive","The registry rejects corrections once a curve is written","Every other app reads the registry copy, so the error propagates to everyone instead of staying local","Local files are backed up more often"]'::jsonb, 2, 'Downstream apps never re-parse the LAS file; they read the registry. A bad registry curve becomes everyone''s problem, which is why QC gates publishing.'),
  ('welldata', 'beginner', 'module', 'm02-the-las-format', 1, 'What does the acronym LAS stand for, and which body published the original standard?', '["Logging Acquisition System, published by the Society of Petrophysicists and Well Log Analysts","Log ASCII Standard, published by the Canadian Well Logging Society","Linear Array Sonde, published by the American Petroleum Institute","Log Archive Schema, published by the Society of Exploration Geophysicists"]'::jsonb, 1, 'LAS is the Log ASCII Standard, published by the Canadian Well Logging Society in the late 1980s so that log data could move between offices as plain, human-readable ASCII text rather than on proprietary vendor tape formats.'),
  ('welldata', 'beginner', 'module', 'm02-the-las-format', 2, 'A LAS file arrives declaring VERS 3.0. What does the app''s importer do with it?', '["Refuses it with a clear message and asks for a LAS 2.0 export","Reads only its first data section and warns that later sections were dropped","Converts it silently to 2.0 rules and imports whatever it can recognise","Treats it as 2.0 because the header grammar is identical in both versions"]'::jsonb, 0, 'LAS 3.0 is out of scope for this parser, and the design rule is to refuse loudly rather than corrupt quietly. The file is rejected with a message asking for a LAS 2.0 export and re-import, instead of being half-parsed.'),
  ('welldata', 'beginner', 'module', 'm02-the-las-format', 3, 'Which two entries live in the ~V section of every LAS file?', '["STRT and STOP","VERS and NULL","WRAP and STEP","VERS and WRAP"]'::jsonb, 3, 'The version section carries VERS, the standard version, and WRAP, which says whether data lines are wrapped. STRT, STOP, STEP and NULL all live in the ~W well section instead.'),
  ('welldata', 'beginner', 'module', 'm02-the-las-format', 4, 'Which pair of LAS sections is optional, so that a reader must not require them?', '["~W and ~C","~V and ~A","~C and ~P","~P and ~O"]'::jsonb, 3, 'The parameter section ~P and the free-text other section ~O are optional. The teaching set proves it: basic_20.las carries both, while wrapped_12.las carries neither and jumps straight from ~Curve Information to ~ASCII.'),
  ('welldata', 'beginner', 'module', 'm02-the-las-format', 5, 'Inside a LAS data block, a line appears whose first character is a tilde. How must a conforming reader treat it?', '["As data, because everything after the ~A title line is data","As the start of a new header section, closing the data block","As a comment, because tildes are ignored inside ~A","As a fatal error, because tildes are illegal after ~A"]'::jsonb, 0, 'Data is terminal. Once the reader crosses the ~A title line, everything that follows belongs to the data block, even a line starting with a tilde. There is no way to close the data section and resume headers, which is why ~A must come last.'),
  ('welldata', 'beginner', 'module', 'm02-the-las-format', 6, 'In the header grammar MNEM.UNIT VALUE : DESCRIPTION, where does the value field end?', '["At the first colon on the line","At the last colon on the line","At the first whitespace after the unit","At the end of the line, with the description taken from the next line"]'::jsonb, 1, 'The value runs greedily to the last colon on the line, matching lasio. Real header values legitimately contain colons, so splitting at the first colon would truncate them; the cost is that a description can never itself contain a colon.'),
  ('welldata', 'beginner', 'module', 'm02-the-las-format', 7, 'quirks_20.las contains the well line ` WELL.           KETA G1-3: THE "QUIRKY" ONE :WELL NAME`. What value does the parser extract?', '["KETA G1-3","WELL NAME","KETA G1-3: THE \"QUIRKY\" ONE","THE \"QUIRKY\" ONE :WELL NAME"]'::jsonb, 2, 'Splitting at the last colon leaves the value as KETA G1-3: THE "QUIRKY" ONE, with WELL NAME as the description. The colon inside the value survives precisely because only the final colon separates value from description.'),
  ('welldata', 'beginner', 'module', 'm02-the-las-format', 8, 'Why are UWI and API values never converted to numbers by the parser?', '["Because they are always longer than a float can represent exactly","Because their leading zeros are significant and would be destroyed","Because they may legally contain a unit field","Because LAS 1.2 places them after the colon rather than before it"]'::jsonb, 1, 'Identifiers such as UWI and API keep their leading zeros as part of their identity, so a numeric conversion would silently destroy information. The parser keeps them as strings while recognising numbers elsewhere in the header.'),
  ('welldata', 'beginner', 'module', 'm02-the-las-format', 9, 'wrapped_12.las carries the well line `WELL.   WELL : KETA G1-2`. Why does the parser report the well name as KETA G1-2 rather than WELL?', '["Because the well name is also recorded in the ~P parameter section","Because a value equal to its own mnemonic is always discarded","Because the file declares VERS 1.2, and 1.2 well-section string entries put the value after the colon","Because the ~C curve section overrides ambiguous well-section entries"]'::jsonb, 2, 'In LAS 1.2, string entries in the well section put the value after the colon, so the parser swaps value and description for those entries once it has read VERS 1.2. STRT, STOP, STEP and NULL keep the value-first layout even in 1.2.'),
  ('welldata', 'beginner', 'module', 'm02-the-las-format', 10, 'In basic_20.las the first data row reads ` 1500.0000    43.1351     2.1893     0.2338   399.7369`. What tells a reader that 2.1893 is a bulk density?', '["Its position, third in the row, matched against the third entry in the ~C section","Its magnitude, since only density values fall between 2 and 3","A unit code embedded in the data row itself","The order of curves in the ~P parameter section"]'::jsonb, 0, 'The ~C section is the column key. It declares DEPT, GR, RHOB, NPHI, DT in that order, so the third number in every row is RHOB in G/C3. The columns never change order mid-file.'),
  ('welldata', 'beginner', 'module', 'm02-the-las-format', 11, 'basic_20.las spans 1500 to 1650 m at a 0.5 m step. How many data rows must it contain?', '["300","301","150","601"]'::jsonb, 1, 'The count follows from the header: (1650 - 1500) / 0.5 + 1 = 301 rows. The plus one counts the first sample, and 301 is one of the six numbers the Associate capstone grades.'),
  ('welldata', 'beginner', 'module', 'm02-the-las-format', 12, 'A LAS file declares five curves, and its data section tokenises to 754 numbers. What does the parser do?', '["Reads 150 complete samples and discards the leftover values","Pads the final sample with the NULL value to complete it","Reports the file as ragged or truncated and refuses it","Re-reads the file assuming four curves instead of five"]'::jsonb, 2, '754 is not an exact multiple of 5, so the file is ragged or truncated. The parser reports exactly that rather than shifting every later column by one, because a silent one-column shift leaves every value looking plausible while attached to the wrong curve.'),
  ('welldata', 'beginner', 'module', 'm02-the-las-format', 13, 'How is missing data represented inside a LAS data block?', '["As an empty field, leaving that row shorter than the others","As the literal text NULL in the affected column","As a row omitted entirely, leaving a gap in the depth sequence","As the sentinel number declared by NULL in the well section, written into the grid"]'::jsonb, 3, 'Missing data is never blank. The well section declares a sentinel, -999.25 in five of the teaching files, and that number is written literally into the grid. The parser substitutes it with NaN on the full-precision parsed value, so -999.2500 in the text matches a declared NULL of -999.25.'),
  ('welldata', 'beginner', 'module', 'm02-the-las-format', 14, 'In wrapped_12.las the record ` 1500.0000` is followed by `   43.1351     2.1893` and then `    0.2338   399.7369`. How many samples do those three lines represent?', '["One sample of five curve values","Three samples, one per physical line","Two samples, since the depth line is a header","Five samples, one per curve value"]'::jsonb, 0, 'In wrap mode the depth starts the record on its own line and the curve values continue on following lines. Those three physical lines carry DEPT 1500.0, GR 43.1351, RHOB 2.1893, NPHI 0.2338 and DT 399.7369, which is one sample.'),
  ('welldata', 'beginner', 'module', 'm02-the-las-format', 15, 'wrapped_12.las spans 1500 to 1580 m at a 0.5 m step, with each depth step occupying three physical lines. What does a naive line-per-sample reader report, and what is the correct answer?', '["It reports 161 samples, and the correct count is 483","It reports 483 samples, and the correct count is 161","It reports 805 samples, and the correct count is 161","It reports 161 samples, which happens to be correct because the depth line anchors each record"]'::jsonb, 1, 'The correct count is (1580 - 1500) / 0.5 + 1 = 161 samples. Each occupies three physical lines, so a reader that counts lines reports 483, three times too many, with every value after the first attached to the wrong curve.'),
  ('welldata', 'beginner', 'module', 'm03-depth-units-and-steps', 1, 'The feet_20 header declares STRT 4900 F. Using the exact international foot, what is the converted start depth in metres?', '["1490.00 m","1524.00 m","1493.52 m","16076.12 m"]'::jsonb, 2, '1 ft = 0.3048 m exactly, so 4900 x 0.3048 = 1493.52 m. 1524 m is the conversion of 5000 ft, not 4900 ft, and dividing by 0.3048 instead of multiplying gives the absurd 16076 m.'),
  ('welldata', 'beginner', 'module', 'm03-depth-units-and-steps', 2, 'feet_20 declares STEP 2 F. What is the converted logging step in metres, carried to the precision the capstone grades (tolerance 0.001 m)?', '["0.6096 m","0.6 m","0.61 m","6.096 m"]'::jsonb, 0, '2 x 0.3048 = 0.6096 m exactly. Rounding it to 0.6 m or 0.61 m is the error the lesson warns about: converted grids are ugly and correct, and the step must not be beautified at import.'),
  ('welldata', 'beginner', 'module', 'm03-depth-units-and-steps', 3, 'A regular depth grid runs from 4900 ft to 5200 ft at a 2 ft spacing. How many depth samples does it hold?', '["149","150","152","151"]'::jsonb, 3, '(5200 - 4900) / 2 + 1 = 150 + 1 = 151. The plus one is the fence-post term, because both end points are logged samples. 150 is the number of increments, not the number of samples.'),
  ('welldata', 'beginner', 'module', 'm03-depth-units-and-steps', 4, 'The metric teaching files carry DT in US/M while feet_20 carries DT in US/F. Why does the sonic conversion divide by 0.3048 when the depth conversion multiplies by it?', '["Because sonic slowness is measured in the opposite direction from depth","Because slowness is a per-length quantity, so a longer unit of length in the denominator means more microseconds per unit","Because the LAS format stores sonic curves as reciprocals","Because the sonic tool samples twice per depth increment"]'::jsonb, 1, 'Slowness carries length in the denominator. One metre contains 1/0.3048 = 3.2808 feet of travel, so microseconds per foot become microseconds per metre by dividing by 0.3048. Multiplying instead, the reflex from depth conversion, is wrong by about a factor of ten at typical rock values.'),
  ('welldata', 'beginner', 'module', 'm03-depth-units-and-steps', 5, 'A sonic reading of 100 US/F is imported from feet_20. What is the equivalent value in US/M?', '["30.5 US/M","100 US/M","328.1 US/M","3280.8 US/M"]'::jsonb, 2, '100 / 0.3048 = 328.1 US/M. Multiplying by 0.3048 gives 30.5 US/M, which still looks like a plausible slowness in some unit and would sail through casual inspection, which is exactly why the conversion must be explicit.'),
  ('welldata', 'beginner', 'module', 'm03-depth-units-and-steps', 6, 'Someone imports feet_20 but rounds the converted step from 0.6096 m to 0.6 m. Over the 150 increments of the well, how far off is the bottom sample and in which direction?', '["1.44 m shallow of the true depth","1.44 m deep of the true depth","0.0096 m shallow of the true depth","0.96 m shallow of the true depth"]'::jsonb, 0, 'Each increment is shortened by 0.6096 - 0.6 = 0.0096 m, and 0.0096 x 150 = 1.44 m. Because every increment is short, the grid lands shallow of where the data actually is, an error larger than the logging step itself.'),
  ('welldata', 'beginner', 'module', 'm03-depth-units-and-steps', 7, 'irregular_20 spans 1500 m to 1560 m and holds 121 depth samples. What is the average increment, and what does that value prove about the grid?', '["0.4959 m, and it proves the grid is irregular","0.5 m, and it proves the grid is uniform at 0.5 m","0.6096 m, and it proves the file needs converting","0.5 m, and it proves nothing about whether the grid is uniform"]'::jsonb, 3, '(1560 - 1500) / (121 - 1) = 60 / 120 = 0.5 m exactly. That is precisely the trap the file exists to teach: the end points and sample count are consistent with a uniform grid while the interior increments wander, so the average is a sanity number and never a verdict.'),
  ('welldata', 'beginner', 'module', 'm03-depth-units-and-steps', 8, 'What does the engine''s step checker, uniformStepM, return when it is run on the depth vector of irregular_20?', '["0.5, the average increment","null, because no single increment holds all the way down the column","0, matching the value declared in the header","The largest increment found in the column"]'::jsonb, 1, 'uniformStepM reads the first increment and compares every subsequent increment against it within a tight tolerance. Any disagreement means no uniform step exists and the function returns null, so the import summary reports irregular_20 as irregular with no step.'),
  ('welldata', 'beginner', 'module', 'm03-depth-units-and-steps', 9, 'The ~Well section of irregular_20 reads STRT 1500 M, STOP 1560 M, STEP 0 M. What does a declared STEP of 0 mean under the LAS convention?', '["The samples all sit at the same depth","The step field was left blank by the export software and carries no meaning","The sampling is not constant, so the step must be read from the data","The file has been resampled and the original step was discarded"]'::jsonb, 2, 'STEP 0 is the format''s way of saying the spacing is not constant, go look at the data. In this file the header is therefore honest, but nothing in the format enforces honesty: the header is a statement of intent and the depth column is the fact.'),
  ('welldata', 'beginner', 'module', 'm03-depth-units-and-steps', 10, 'basic_20 runs from 1500 m to 1650 m with a uniform 0.5 m step. How many depth samples does it contain?', '["301","300","299","151"]'::jsonb, 0, '(1650 - 1500) / 0.5 + 1 = 300 + 1 = 301. Dropping the plus one gives 300, the increment count rather than the sample count.'),
  ('welldata', 'beginner', 'module', 'm03-depth-units-and-steps', 11, 'A LAS file arrives whose depth curve carries a unit spelling the importer does not recognise. What does the importer do?', '["Assumes metres, because metres are the platform''s internal standard","Assumes feet, because unfamiliar spellings usually come from older North American files","Imports the file and lets a downstream QC check settle the unit","Refuses to import the file rather than guess the depth unit"]'::jsonb, 3, 'The importer recognises M, METRE, METRES, METER, METERS, F, FT and FEET, and refuses anything else. A wrong guess shifts every measurement in the well by roughly a factor of three, and no downstream QC catches it once the data sits in the registry wearing a metres label.'),
  ('welldata', 'beginner', 'module', 'm03-depth-units-and-steps', 12, 'A LAS file declares STRT 3000 F, STOP 3100 F, STEP 5 F on a regular grid. What are its sample count and its converted step in metres?', '["20 samples, step 1.524 m","21 samples, step 1.524 m","21 samples, step 1.5 m","20 samples, step 15.24 m"]'::jsonb, 1, '(3100 - 3000) / 5 + 1 = 20 + 1 = 21 samples, and 5 x 0.3048 = 1.524 m. Rounding the step to 1.5 m would shorten each of the 20 increments by 0.024 m, putting the base of the log 0.48 m shallow.'),
  ('welldata', 'beginner', 'module', 'm03-depth-units-and-steps', 13, 'The import summary for feet_20 reports two curves converted. Which two, and why do the others need nothing?', '["Depth and gamma ray, because GAPI is defined per foot in North American practice","Density and neutron, because G/C3 and V/V are volumetric units","Depth and sonic, because both are length-referenced while GAPI, G/C3 and V/V are not","Depth only counts as one conversion, and the second is the STEP entry in the header"]'::jsonb, 2, 'The depth column converts F to M and the sonic converts US/F to US/M, because slowness references length. Gamma ray in GAPI, density in G/C3 and neutron in V/V carry no length reference, so they pass through unconverted.'),
  ('welldata', 'beginner', 'module', 'm03-depth-units-and-steps', 14, 'The beginner''s discipline names three checks on a depth grid: read the header step, compute the average step, and compare every increment. Which one delivers the verdict?', '["The increment-by-increment comparison, because it is the only definition of uniform that cannot be faked","The header step, because the export software wrote it from the acquisition settings","The average step, because it uses every sample in the file","Any of the three, since a well-formed LAS file makes all three agree"]'::jsonb, 0, 'The header is a claim and the average is a sanity number. Only the increment-by-increment check counts, which is why irregular_20 passes the average test with an exact 0.5 m and still fails uniformity.'),
  ('welldata', 'beginner', 'module', 'm03-depth-units-and-steps', 15, 'An irregular well arrives at import. According to the module''s rule set, what should the parser do with it?', '["Resample it onto the nearest round step so downstream thickness logic has a spacing to use","Reject the file, since curve arithmetic cannot be trusted on an irregular grid","Write the average increment into the step field so the file looks uniform to consumers","Keep the logged depth column untouched, record the step as unknown, and flag the file for explicit resampling later"]'::jsonb, 3, 'The parser''s job is fidelity. Resampling changes the data by choosing a spacing and an interpolation, so it is a modelling decision that belongs to a later explicit stage with the original samples preserved underneath. A parser that quietly regrids destroys evidence, and writing an average step hides the irregularity from thickness logic that keys off the honest null.'),
  ('welldata', 'beginner', 'module', 'm04-nulls-and-data-quality', 1, 'In a LAS file, what does the NULL line in the well information (~W) section do?', '["It sets the depth at which the log data begins.","It declares, for that file, the numeric value that means ''no measurement here''.","It fixes the global sentinel for all LAS files at -999.25.","It lists which curves contain missing data."]'::jsonb, 1, 'The NULL line is a per-file declaration of the sentinel value. From that line onward, every occurrence of the declared number in the data section means absent rather than measured. It is a declaration, not a constant, and not a per-curve list.'),
  ('welldata', 'beginner', 'module', 'm04-nulls-and-data-quality', 2, 'nullheavy_20 declares NULL as -9999. A reader hard-coded to assume -999.25 opens the file. What null count does it report for that file''s GR curve?', '["71, because the sentinel count does not depend on the reader.","130, because it counts the finite samples instead.","0, because no cell in the file contains -999.25.","201, because it treats the whole column as suspect."]'::jsonb, 2, 'No cell holds -999.25, so the hard-coded reader finds no matches and reports zero nulls. All 71 entries of -9999 are then treated as real gamma ray readings and fed into the statistics.'),
  ('welldata', 'beginner', 'module', 'm04-nulls-and-data-quality', 3, 'basic_20 has 301 samples and its GR curve carries 8 nulls. How many finite GR samples are there, and which count is the correct divisor for the GR mean?', '["293 finite samples, and 293 is the divisor.","293 finite samples, but 301 is the divisor because that is the column length.","301 finite samples, and 301 is the divisor because nulls are still samples.","8 finite samples, and 8 is the divisor."]'::jsonb, 0, '301 - 8 = 293 finite samples. A statistic describes the population it is computed over, so both the sum and the divisor must use the finite samples only. Dividing the correct finite sum by 301 would give 19023.6696 / 301 = 63.2016 instead of the true 64.9272.'),
  ('welldata', 'beginner', 'module', 'm04-nulls-and-data-quality', 4, 'nullheavy_20 has 201 samples and 71 GR nulls. Over how many samples is its GR mean of 44.3489 GAPI computed?', '["201, the full column length.","71, the flagged samples.","160, an approximate usable count.","130, the finite samples."]'::jsonb, 3, '201 - 71 = 130 finite samples. The mean of 44.3489 GAPI describes those 130 real readings only. Dividing the same finite sum by 201 would report 28.6834, understating the gamma ray by more than a third.'),
  ('welldata', 'beginner', 'module', 'm04-nulls-and-data-quality', 5, 'basic_20''s GR has 293 finite samples with a mean of 64.9272 GAPI and 8 sentinels of -999.25. If the eight sentinels were included as data, what mean would result?', '["36.6434 GAPI","64.9272 GAPI, because eight values cannot move a mean of 301 samples.","-999.25 GAPI","63.2016 GAPI"]'::jsonb, 0, '(293 x 64.9272 + 8 x (-999.25)) / 301 = 11029.67 / 301 = 36.6434 GAPI. The value 63.2016 is a different error, the correct finite sum divided by 301.'),
  ('welldata', 'beginner', 'module', 'm04-nulls-and-data-quality', 6, 'Why is the poisoned basic_20 GR mean of 36.6434 GAPI more dangerous than the poisoned RHOB mean of -27.6086 for the same file?', '["Because gamma ray matters more to interpretation than bulk density does.","Because 36.6434 is a physically believable gamma ray, so nothing on the page flags it as wrong.","Because the GR error is larger in absolute terms.","Because RHOB has fewer nulls than GR."]'::jsonb, 1, 'A negative bulk density is impossible and any reviewer would catch it. A gamma ray of 36.64 GAPI reads as a plausible clean sand, so a poisoned GR mean can pass through a whole report unchallenged. Silent errors are the expensive ones. RHOB in fact has more nulls (9) than GR (8).'),
  ('welldata', 'beginner', 'module', 'm04-nulls-and-data-quality', 7, 'A curve''s mean is computed by summing only the finite samples but dividing by the total sample count. What is the effect?', '["No effect, because the sentinels were excluded from the sum.","The mean becomes NaN, so the mistake announces itself.","The mean is pulled toward zero by the fraction of the column that is missing, with no warning of any kind.","The mean is inflated in proportion to the number of nulls."]'::jsonb, 2, 'The numerator is right but the divisor is too large, so the result is scaled down by the finite fraction. For basic_20''s GR that gives 19023.6696 / 301 = 63.2016 instead of 64.9272. No impossible value appears, which is what makes the divisor mistake easy to miss.'),
  ('welldata', 'beginner', 'module', 'm04-nulls-and-data-quality', 8, 'What exactly makes a curve dead, as the QC panel defines it?', '["Its null count exceeds fifty percent of its samples.","It has no mean because its readings are all identical.","It is missing from the curve section (~C).","Its null count is exactly equal to its sample count."]'::jsonb, 3, 'The dead test is exact: nulls equal samples, so no cell in the column carries a measurement. There is no percentage threshold. A dead curve is still declared in ~C and still occupies a full column; that is precisely the trap.'),
  ('welldata', 'beginner', 'module', 'm04-nulls-and-data-quality', 9, 'nullheavy_20''s NPHI is 201 nulls out of 201 samples. What should its mean, first finite and last finite cells show?', '["All three blank, because there is no finite sample to compute them over.","Mean 0.0000, with first and last finite at the top and bottom of the logged interval.","Mean -9999, since that is the only value present in the column.","Mean 0.2416, borrowed from basic_20''s NPHI as the default."]'::jsonb, 0, 'The finite population is empty, so there is nothing to average and no first or last reading to report. Blank is the correct answer. A zero would claim a measurement that was never made, and -9999 is the sentinel, not data.'),
  ('welldata', 'beginner', 'module', 'm04-nulls-and-data-quality', 10, 'Would a curve with 200 nulls out of 201 samples be classified as dead?', '["Yes, because 99.5 percent null rounds to totally absent.","Yes, because a single sample cannot support a mean.","No, because one finite sample means it fails the exact nulls-equal-samples test, though it should still be flagged as unusable.","No, and it needs no comment because it still has statistics."]'::jsonb, 2, 'The definition is exact, so 200 of 201 is not dead. In practice the curve is useless and should be flagged and recorded as such, but calling it dead would misstate the test.'),
  ('welldata', 'beginner', 'module', 'm04-nulls-and-data-quality', 11, 'basic_20''s GR carries 8 nulls out of 301 samples, and they sit at the ends of the column. What does that pattern normally indicate?', '["A washout interval where the tool could not read against the borehole wall.","Run-in and run-out, where the tool starts and stops recording slightly inside the logged interval.","A splice gap where two runs failed to overlap.","A failed cartridge that killed the channel mid-run."]'::jsonb, 1, 'A few nulls at the ends of a curve are the signature of run-in and run-out. At 8 / 301 = 2.7 percent the loss is cosmetic and the measurements that exist are fine. Washouts and splices produce blocks in the middle of the column instead.'),
  ('welldata', 'beginner', 'module', 'm04-nulls-and-data-quality', 12, 'nullheavy_20''s GR has 71 nulls out of 201 samples, forming a large contiguous block. What is the correct verdict on the curve?', '["It is dead and should be dropped from the registry.","It is fine, because 130 samples is a large enough sample size.","It should be discarded, because any curve above 30 percent null is unusable.","It is trustworthy where it reads and absent where it does not, so any interval statistic must state that it covers 130 samples."]'::jsonb, 3, '71 / 201 = 35.3 percent of the interval was never logged. The curve is wounded, not dead, and remains usable where it reads. What the report owes the reader is the footnote: the quoted mean of 44.3489 GAPI describes 130 samples, not the whole interval.'),
  ('welldata', 'beginner', 'module', 'm04-nulls-and-data-quality', 13, 'basic_20''s GR has its first finite value 43.14 at 1500.0 m and its last finite value 56.76 at 1650.0 m. What do those two entries tell you?', '["The minimum and maximum gamma ray readings in the curve.","The depth bounds over which the curve actually carries data, here an interval of 150.0 m.","The depths at which the tool was calibrated.","The two samples that were flagged null at the run boundaries."]'::jsonb, 1, 'First finite and last finite are the depths where real readings begin and end, giving 1650.0 - 1500.0 = 150.0 m of supported interval. They are not extremes of value, and they are finite samples, not nulls. Where several curves are needed, the usable interval is the overlap of their finite ranges.'),
  ('welldata', 'beginner', 'module', 'm04-nulls-and-data-quality', 14, 'Why does the parser convert every flagged value to NaN instead of leaving the sentinel number in the array?', '["Because NaN takes less memory than a floating-point sentinel.","Because NaN restores the missing measurement by interpolation.","Because NaN contaminates any arithmetic it touches, so a computation that forgets to filter fails loudly instead of returning a plausible wrong number.","Because the LAS standard requires NaN in the data section."]'::jsonb, 2, 'NaN is contagious: any sum, mean or comparison touching it returns NaN. That turns a silent poisoning, such as the plausible-looking 36.6434 GAPI, into a visible failure. The engine then filters to the finite samples deliberately, so the QC panel''s mean column is finite-only by construction.'),
  ('welldata', 'beginner', 'module', 'm04-nulls-and-data-quality', 15, 'A dead curve arrives in a delivered file. What are the two defensible QC choices, and what does each protect?', '["Interpolate it from neighbouring curves, or leave it untouched for the interpreter to handle.","Flag it as dead to preserve the record of what the vendor supplied, or drop it so no tool or person mistakes it for data.","Replace the sentinels with zeros, or rename the curve so downstream software ignores it.","Re-declare the file''s NULL value, or delete the file and request a redelivery."]'::jsonb, 1, 'Flagging keeps the audit trail of the delivery; dropping keeps the working registry honest. Either can be right. The failure mode is making no decision and letting the dead column masquerade as data, and whichever is chosen must be recorded: which curve, which file, which choice, and why.'),
  ('welldata', 'beginner', 'module', 'm05-headers-and-metadata', 1, 'Which LAS section holds the entries that tell you where a well is, who logged it, and how the numbers that follow should be read?', '["The ~Curve section","The ~Well section","The ~Version section","The ~Other section"]'::jsonb, 1, 'The well section, which starts with ~Well, carries both the framing entries (STRT, STOP, STEP, NULL) and the identity entries (WELL, COMP, FLD, LOC, SRVC, DATE, UWI). The curve section names the data columns and the version section declares VERS and WRAP.'),
  ('welldata', 'beginner', 'module', 'm05-headers-and-metadata', 2, 'In the header line STRT.M  1500.0000 : START DEPTH, which part is the unit?', '["START DEPTH, the text after the colon","1500.0000, the numeric field","M, the text attached after the dot","STRT, the mnemonic"]'::jsonb, 2, 'The grammar is mnemonic, dot, unit, value, colon, description. STRT is the mnemonic, M is the unit sitting immediately after the dot, 1500.0000 is the value and START DEPTH is the description. Entries with no sensible unit, such as NULL and COMP, leave that slot empty.'),
  ('welldata', 'beginner', 'module', 'm05-headers-and-metadata', 3, 'Why does the course call framing errors loud and identity errors quiet?', '["Framing entries appear first in the file, so readers notice them sooner","Identity entries are optional in LAS, so parsers reject files that contain them","A wrong NULL or STEP corrupts computed numbers visibly, while a wrong well name parses cleanly and passes every numeric check","Framing entries are numeric and therefore always validated by the parser"]'::jsonb, 2, 'A wrong NULL drags averages to absurd values and a wrong STEP breaks resampling, both of which show up in the numbers. A wrong WELL name produces a file that parses perfectly and passes every numeric test while attaching curves to the wrong borehole.'),
  ('welldata', 'beginner', 'module', 'm05-headers-and-metadata', 4, 'quirks_20 uses ragged spacing around its dots and colons, and its comment lines draw a column ruler that does not line up with the entries. What does this defeat?', '["Any reader that locates the value by fixed character positions","Any reader that treats whitespace as a separator","The LAS standard itself, since ragged spacing is illegal","The parser''s ability to read the ~ASCII data section"]'::jsonb, 0, 'Column-position parsing tuned to a tidy file such as basic_20 returns nonsense on quirks_20, and does so silently. Grammar-based parsing, which finds the dot and the colon and trims the whitespace between them, reads the file correctly.'),
  ('welldata', 'beginner', 'module', 'm05-headers-and-metadata', 5, 'The WELL entry in quirks_20 is KETA G1-3: THE "QUIRKY" ONE. What does a reader that splits each header line at the FIRST colon report as the well name?', '["KETA G1-3: THE \"QUIRKY\" ONE, unchanged","WELL NAME","An error, because the line cannot be parsed","KETA G1-3, silently truncated"]'::jsonb, 3, 'Splitting at the first colon cuts the value short at KETA G1-3 and pushes the rest into the description. The truncated name looks perfectly plausible, which is what makes the failure dangerous.'),
  ('welldata', 'beginner', 'module', 'm05-headers-and-metadata', 6, 'How does the engine''s parser decide where the value ends and the description begins on a header line?', '["The value runs to the first colon on the line","The value runs greedily to the last colon on the line, and the description follows it","The value is whatever sits between fixed columns 17 and 40","The value always follows the colon, and the description precedes it"]'::jsonb, 1, 'The value runs greedily to the last colon, so colons inside a value survive. On the quirks_20 WELL line the last colon is the one before WELL NAME, so the value comes back as KETA G1-3: THE "QUIRKY" ONE with WELL NAME as the description.'),
  ('welldata', 'beginner', 'module', 'm05-headers-and-metadata', 7, 'quirks_20 has no COMP, FLD, LOC, SRVC or DATE entry. What is the correct reading of that?', '["The file is malformed and must be rejected before import","The parser will substitute defaults for the missing entries","It is legal LAS and common in practice, but it means the provenance of the curves is unknown","It makes no difference, because those entries never affect anything"]'::jsonb, 2, 'The LAS standard requires very little of the well section, so a thin header parses without error. Absence is still information: you cannot say who logged these curves, for whom, in which field, or on which date, and nothing in the header can arbitrate a later disagreement.'),
  ('welldata', 'beginner', 'module', 'm05-headers-and-metadata', 8, 'irregular_20 declares STEP.M 0.0000. What does a declared step of zero mean?', '["The depth column is missing from the data section","The file is a single-sample file with no depth increment","The step entry was left blank by mistake and should be treated as unknown corruption","It is the LAS convention for a file whose depth samples are not evenly spaced"]'::jsonb, 3, 'A step of zero is the export honestly announcing irregular sampling. There is no single increment to declare, so the file declares none, and the depth column must be treated as data rather than as arithmetic regenerated from STRT and STEP.'),
  ('welldata', 'beginner', 'module', 'm05-headers-and-metadata', 9, 'irregular_20 spans 1500 to 1560 m in 121 samples with increments that cycle through 0.3, 0.5 and 0.7 m. What is the average increment, and what does uniformStepM return?', '["Exactly 0.5 m, and uniformStepM returns null because the increments are not constant","Exactly 0.5 m, and uniformStepM returns 0.5 because the average matches","0.3 m, the first increment, and uniformStepM returns 0.3","It cannot be computed, and uniformStepM throws an error"]'::jsonb, 0, 'There are 120 increments over a 60 m span, so the average is (1560 - 1500) / 120 = 0.5 m exactly, even though no single increment equals 0.5. uniformStepM compares every increment against the first within a tolerance and returns null as soon as one differs.'),
  ('welldata', 'beginner', 'module', 'm05-headers-and-metadata', 10, 'Consider a file with irregular_20''s exact depth column but a header that dishonestly declares STEP 0.5. Which check catches it?', '["Comparing STRT against STOP, which are inconsistent","Comparing the expected sample count against the actual row count","Recomputing the increments from the depth column and comparing them against the declared step","Checking that the declared NULL value appears in the data"]'::jsonb, 2, 'STRT and STOP are consistent, and the expected count (1560 - 1500) / 0.5 + 1 = 121 matches the 121 rows because the average increment really is 0.5 m. Only walking the depth column exposes the contradiction, at the very first pair of increments.'),
  ('welldata', 'beginner', 'module', 'm05-headers-and-metadata', 11, 'nullheavy_20 declares NULL -9999.00 rather than the customary -999.25. If you assumed -999.25 and averaged all 201 GR samples, what would happen?', '["The parser would raise an error because no sample matches the assumed flag","The mean would be far too low, near -3503 instead of about 44.35 API","The mean would be unchanged, because 71 nulls are too few to matter","The mean would be too high, because null flags are large positive numbers"]'::jsonb, 1, 'Seventy-one of the 201 GR samples carry -9999. Honouring the declaration and averaging the 130 real samples gives about 44.35 API. Assuming -999.25 means nothing matches, all 201 values are treated as measurements, and the mean collapses to about -3503. Nothing crashes; you simply get an absurd number.'),
  ('welldata', 'beginner', 'module', 'm05-headers-and-metadata', 12, 'Which statement best expresses the trust but verify rule for LAS headers?', '["The header is authoritative, so recomputing from the data wastes time","The data is authoritative, so the header can be ignored entirely","The header is a claim, the data is the evidence, and QC is the comparison between them","A file that parses without error has been verified"]'::jsonb, 2, 'Header entries are claims written by whoever built the file. QC recomputes first depth, last depth, increment behaviour, sample count and null count from the samples and reads the header beside them. A claim that has not been compared against evidence has not been checked.'),
  ('welldata', 'beginner', 'module', 'm05-headers-and-metadata', 13, 'After a file passes QC and is published to the shared registry, what does the well name become?', '["The join key that links these curves to tops, checkshots and zones across every downstream app","A display label only, since apps join on the file name","A value the registry recomputes from the depth range","Documentation that no application actually reads"]'::jsonb, 0, 'Tops, checkshots, surveys and zones all arrive from different apps on different days and are bound into one well by identity, with the well name doing most of the joining. Petrophysics, correlation, synthetics and mapping all fetch by name.'),
  ('welldata', 'beginner', 'module', 'm05-headers-and-metadata', 14, 'Publishing one file as KETA G1-1 and a later one as Keta G1_1 produces which failure?', '["A parse error on the second import, since the name conflicts","Two registry wells, each holding part of one borehole''s data, with no error raised","The registry silently merges them, because name matching ignores case and punctuation","The second file overwrites the first well''s curves"]'::jsonb, 1, 'Two different strings are simply two different wells. The tops sit on one and the sonic on the other, both look complete, neither is, and nothing raises a flag. Case, hyphens against underscores, doubled spaces and invisible trailing spaces are all it takes.'),
  ('welldata', 'beginner', 'module', 'm05-headers-and-metadata', 15, 'In the teaching set, the UWI entries differ across the four files that share the well name KETA G1-1 (KETA-G1-BASIC, KETA-G1-FEET, KETA-G1-IRREG, KETA-G1-NULLS). What is the lesson?', '["The UWI is always the safest identity key, so it should override the well name","The four files are therefore four different boreholes and must be kept apart","UWI entries should be deleted from headers before publishing","In this set the UWI identifies the file rather than the borehole, so using it as the identity key would split one well into four"]'::jsonb, 3, 'A real UWI is a proper unique identifier and outranks the name, but here each file carries its own tag. That is exactly why you check what a given file actually puts in the field instead of assuming, and never silently edit header values to make them agree.'),
  ('welldata', 'beginner', 'module', 'm06-the-qc-workflow', 1, 'In the import checklist, which check comes immediately after Structure?', '["Identity, so you know whose file you are looking at before anything else","Framing, the depth unit, range, step and uniformity","Plausibility, so bad numbers are caught as early as possible","Completeness, because null counts decide whether the rest is worth running"]'::jsonb, 1, 'The order is Structure, Framing, Completeness, Plausibility, Identity. Framing sits second because the depth frame is the skeleton every curve hangs on, so a framing error contaminates every check after it.'),
  ('welldata', 'beginner', 'module', 'm06-the-qc-workflow', 2, 'Why does the checklist put Completeness ahead of Plausibility?', '["Null counts are faster to compute than curve statistics, so they cost less time","Plausibility is optional for files that already parsed cleanly","A statistic can look perfectly physical while it is computed over a curve that is missing much of its data","The parser cannot compute a mean until the null counts have been recorded"]'::jsonb, 2, 'The lesson uses nullheavy_20 to make this point: its finite GR mean is a physically sensible value, so plausibility alone would wave through a gamma ray missing more than a third of its samples. Completeness has to run first to expose that.'),
  ('welldata', 'beginner', 'module', 'm06-the-qc-workflow', 3, 'Flagging a dead curve, meaning a curve whose every sample is null, belongs to which checklist step?', '["Completeness","Structure","Plausibility","Framing"]'::jsonb, 0, 'Completeness asks whether the data is actually there: it confirms the declared NULL is honoured, reads per-curve null counts, and flags any curve that is entirely null. A dead curve is listed in the curve section but carries no usable data.'),
  ('welldata', 'beginner', 'module', 'm06-the-qc-workflow', 4, 'What does the Identity check ask of a file?', '["That the file name matches the well name recorded inside it","That the header STRT, STOP and STEP agree with the recomputed values","That the curve mnemonics follow a standard naming scheme","That the well name resolves to a real well and the file''s provenance is recorded"]'::jsonb, 3, 'Identity is the last check: the well must resolve to a real well, and where the file came from and when must be recorded. Data without identity cannot be trusted later, however clean it looks on the day.'),
  ('welldata', 'beginner', 'module', 'm06-the-qc-workflow', 5, 'Which region of the QC panel shows a file''s step twice, once in the native unit and once converted?', '["The header table, in the STEP entry with its unit","The depth range tile, which names the unit in its heading","The Step (native / metres) tile","The per-curve table, in the row for the depth curve"]'::jsonb, 2, 'The Step tile deliberately shows both numbers side by side so the conversion is visible rather than assumed. For feet_20 it reads 2.0000 F and then the metric equivalent.'),
  ('welldata', 'beginner', 'module', 'm06-the-qc-workflow', 6, 'Where in the panel do you read a single curve''s null count and its mean over finite samples?', '["In that curve''s row of the per-curve table, which carries both columns","In the Samples / NULL tile, which reports them per curve","In the header table, alongside the NULL declaration","In two different places: the null count in a tile, the mean in the curve table"]'::jsonb, 0, 'The per-curve table has one row per curve with seven columns: mnemonic, unit, samples, nulls, first finite, last finite, and mean over finite samples. Completeness and plausibility both live in that one row.'),
  ('welldata', 'beginner', 'module', 'm06-the-qc-workflow', 7, 'A row in the per-curve table is rendered in red. What is the panel telling you?', '["The curve''s mean sits outside a physically plausible range","The curve is dead: every one of its samples is null, so there is no first finite, last finite or mean","The curve''s unit could not be recognised and was left unconverted","The curve''s sample count disagrees with the depth sample count"]'::jsonb, 1, 'Red marks a dead curve. On nullheavy_20 the NPHI row turns red with 201 samples and 201 nulls and empty statistics columns. The colour exists because a dead curve is easy to miss when skimming for outliers.'),
  ('welldata', 'beginner', 'module', 'm06-the-qc-workflow', 8, 'When a question names a particular teaching file, what should you do before reading any value?', '["Read the value from whichever file is loaded, then convert it to the named file''s units","Check the header table first, since the file name is recorded there","Reload the app so the parser starts from a clean state","Click that file in the selector and let the panel rebuild, then read"]'::jsonb, 3, 'Clicking a file runs the parser on it and rebuilds everything below the selector. A correct reading taken from the wrong file is still a wrong answer, so confirming the selection is the first habit the panel tour teaches.'),
  ('welldata', 'beginner', 'module', 'm06-the-qc-workflow', 9, 'Which set of quantities does the Associate capstone grade?', '["A written QC verdict on each of the six teaching files, scored against a rubric","The campaign totals across all six files: curves imported, conversions, dead curves and flagged nulls","Six panel readings: basic_20 depth samples, basic_20 GR nulls, basic_20 mean GR over finite samples, feet_20 step in metres, nullheavy_20 NPHI nulls, and wrapped_12 depth samples","The full metric frame of feet_20 plus a pass or fail uniformity verdict on irregular_20"]'::jsonb, 2, 'The capstone grades exactly those six readings, taken from four files and three regions of the QC panel. Campaign totals belong to the Expert tier, and the full metric frame with the uniformity verdict belongs to the Professional tier.'),
  ('welldata', 'beginner', 'module', 'm06-the-qc-workflow', 10, 'What does the Expert tier exercise do that the Professional tier does not?', '["It runs the import across all six teaching files at once and reports totals for the whole delivery","It converts curve units instead of only depth units","It reads the header table rather than relying on recomputed values","It grades readings to a tighter numeric tolerance"]'::jsonb, 0, 'The Expert exercise is a six-file import campaign that audits an entire delivery at once, reporting roll-ups such as total curves imported, files needing conversion, dead curves detected, files with a uniform step, samples parsed from the wrapped file, and total flagged nulls.'),
  ('welldata', 'beginner', 'module', 'm06-the-qc-workflow', 11, 'Which pair of pass marks does the deep path enforce?', '["70 percent on each module quiz and 70 percent on the final exam","75 percent on each module quiz and 70 percent on the final exam","75 percent on each module quiz and 75 percent on the final exam","70 percent on each module quiz and 75 percent on the final exam"]'::jsonb, 1, 'Each module quiz must be passed at 75 percent, and the final exam at 70 percent. The exam threshold is a little lower because it draws across the whole course rather than one module.'),
  ('welldata', 'beginner', 'module', 'm06-the-qc-workflow', 12, 'What happens after three failed attempts on the same module quiz?', '["The module is marked complete at the best score achieved","The lessons in that module are reset to unread","The final exam threshold rises for that learner","A 24 hour cooldown blocks further attempts on that quiz"]'::jsonb, 3, 'Three failures trigger a 24 hour cooldown. It is deliberate: the point is to send the learner back to the lessons rather than allowing repeated guessing through the option list.'),
  ('welldata', 'beginner', 'module', 'm06-the-qc-workflow', 13, 'What does passing the capstone earn, and why does it matter beyond this course?', '["Access to the Professional tier of Well Data Manager, which is otherwise locked","A record of the six readings, which is filed with the well registry","The Associate certification, which is the prerequisite root that opens the rest of the geoscience path","Exemption from the final exam in the courses that follow"]'::jsonb, 2, 'The capstone earns the Associate certification in Well Data Manager. That certificate is the prerequisite root of the whole geoscience path, so petrophysics, correlation, seismic, mapping and volumetrics all sit behind it.'),
  ('welldata', 'beginner', 'module', 'm06-the-qc-workflow', 14, 'How does unit handling at the Professional tier differ from the Associate tier?', '["The pipeline converts units curve by curve rather than on depth alone, so a feet file can have more than one converted curve","The pipeline reports units in the header table instead of on a tile","The pipeline rejects any file whose curves are not already in metric units","The pipeline converts depth only, and leaves other curves to the interpreter"]'::jsonb, 0, 'At the Professional tier every curve''s declared unit is inspected and converted if needed. On feet_20 that means two converted curves, the depth column and the sonic in US/F, which makes the point that unit trouble lives curve by curve rather than file by file.'),
  ('welldata', 'beginner', 'module', 'm06-the-qc-workflow', 15, 'Which line best summarises how the three tiers differ?', '["The beginner loads files, the professional interprets them, the expert publishes them","The beginner reads QC, the professional automates it, the expert audits a campaign","The beginner checks depth, the professional checks curves, the expert checks headers","The beginner works by hand, the professional works from the panel, the expert works from the header"]'::jsonb, 1, 'That single line frames the progression: the Associate tier reads the QC panel, the Professional tier drives the full import pipeline, and the Expert tier audits a whole delivery at once. The underlying checks never change; only the scale and the automation do.'),
  ('welldata', 'beginner', 'final', null, 1, 'Why does the Well Data Manager course sit at the root of the geoscience path, as the prerequisite for every other course?', '["Because every downstream interpretation consumes well data, so the quality of imports bounds the quality of everything built on them","Because it is the shortest course and serves as an orientation module","Because regulators require data management certification before interpretation work","Because the other apps cannot run until a LAS file is uploaded to them directly"]'::jsonb, 0, 'Petrophysics, correlation, synthetics and mapping all read the well registry. If the imported data is wrong, every downstream product inherits the error, so the path starts here.'),
  ('welldata', 'beginner', 'final', null, 2, 'A log runs from 1500 m to 1650 m with a constant 0.5 m step. How many depth samples does it contain?', '["300","301","299","302"]'::jsonb, 1, 'Fence-post counting: (1650 - 1500) / 0.5 = 300 intervals, and intervals + 1 = 301 samples. basic_20 shows exactly this.'),
  ('welldata', 'beginner', 'final', null, 3, 'What is a well log, at its most fundamental?', '["A time-indexed record of drilling operations","A single averaged value per curve for the whole well","A depth-indexed series of physical measurements sampled at regular or irregular increments","A text report describing the lithology seen in cuttings"]'::jsonb, 2, 'A log is measurements against depth. Everything in the course, steps, nulls, statistics, follows from that series structure.'),
  ('welldata', 'beginner', 'final', null, 4, 'Which teaching file is the clean reference case, the recommended starting point before studying the hazard files?', '["quirks_20.las","wrapped_12.las","nullheavy_20.las","basic_20.las"]'::jsonb, 3, 'basic_20 is a clean LAS 2.0 export: standard sections, one NULL value, uniform metric depth. The other files each isolate one real-world hazard.'),
  ('welldata', 'beginner', 'final', null, 5, 'A curve value looks physically implausible after import. What is the data manager''s correct action?', '["Flag and document it, and verify the import chain, without silently editing the stored values","Overwrite the value with an interpolation of its neighbours","Delete the curve so it cannot mislead interpreters","Adjust the value to the nearest plausible number and note nothing"]'::jsonb, 0, 'The data manager''s job is custody and QC, not silent alteration. Documented flags preserve trust; silent edits destroy it.'),
  ('welldata', 'beginner', 'final', null, 6, 'A log runs from 2000 m to 2100 m at a constant 0.25 m step. How many samples is that?', '["400","25","401","101"]'::jsonb, 2, '(2100 - 2000) / 0.25 = 400 intervals, plus one: 401 samples. The interval-versus-sample distinction is the most common counting error.'),
  ('welldata', 'beginner', 'final', null, 7, 'Why does the course use six different teaching files rather than one large example?', '["Six files are needed to fill the six modules","Each file isolates one specific real-world import hazard so its effect can be studied cleanly","The parser can only hold small files in memory","They are six wells from six different fields chosen for geological variety"]'::jsonb, 1, 'basic is the control; feet, irregular, nullheavy, quirks and wrapped each demonstrate one failure mode: units, non-uniform steps, null flooding, header quirks and wrapped records.'),
  ('welldata', 'beginner', 'final', null, 8, 'In a LAS file, which section must the ~A section be, and what does it hold?', '["The last section, holding the columnar depth-indexed data","The first section, holding the version declaration","Anywhere in the file, holding optional comments","Immediately after ~V, holding the curve list"]'::jsonb, 0, '~A (ASCII data) is always last; everything before it is header. The version lives in ~V and the curve list in ~C.'),
  ('welldata', 'beginner', 'final', null, 9, 'The quirks_20 well name is written as KETA G1-3: THE "QUIRKY" ONE. Why does this line break naive LAS parsers?', '["The quotation marks are illegal in LAS 2.0","Well names may not contain digits after a hyphen","A parser that splits the header line on the first colon it finds truncates the value, because this value itself contains a colon","The line exceeds the 80-character limit of the standard"]'::jsonb, 2, 'The header grammar puts the description after a colon, but values can legally contain colons too. A robust parser must not grab the first colon blindly; quirks_20 exists to prove yours does not.'),
  ('welldata', 'beginner', 'final', null, 10, 'wrapped_12.las declares VERS 1.2 and WRAP YES. What does WRAP YES mean for the data section?', '["The file is compressed and must be unwrapped by a utility first","One depth step''s values span several physical lines instead of one line per depth","The depth column restarts from zero partway down","Curve mnemonics are repeated before every data block"]'::jsonb, 1, 'Wrapped mode was common in LAS 1.2 because of line-length limits: each sample''s values continue across multiple lines, and the parser must reassemble them.'),
  ('welldata', 'beginner', 'final', null, 11, 'Which LAS section declares the NULL value that flags missing data?', '["~C, next to each curve","~A, at the top of the data block","~P, with the parameters","~W, the well information section"]'::jsonb, 3, 'NULL is a well-section entry (like STRT, STOP and STEP). It applies to the whole file, which is why the parser must read it rather than assume one.'),
  ('welldata', 'beginner', 'final', null, 12, 'What does the ~C section define?', '["The curves present in the file, with units and descriptions, in the exact column order of the data section","The company and field identity of the well","The calibration coefficients applied by the logging truck","A checksum for each data column"]'::jsonb, 0, '~C is the column map: its order is the data order. If ~C lists five curves, every data record carries five values, depth first by convention.'),
  ('welldata', 'beginner', 'final', null, 13, 'wrapped_12 spans 1500 m to 1580 m at a 0.5 m step, with each sample wrapped across several lines. How many depth samples should the parser deliver?', '["161","The number of physical lines in ~A","320","80"]'::jsonb, 0, '(1580 - 1500) / 0.5 + 1 = 161 samples. Wrapping changes the line layout, never the sample count; a parser that returns the physical line count has failed.'),
  ('welldata', 'beginner', 'final', null, 14, 'A file''s first section reads ~V with VERS. 2.0. What does this tell the parser?', '["The file contains exactly two curves","The header grammar and wrap conventions follow the LAS 2.0 specification","The data is stored in binary from this point on","Depth is guaranteed to be in metres"]'::jsonb, 1, 'The version declaration selects the rules for everything that follows. wrapped_12 declares 1.2 and behaves differently (wrapped data); neither version implies anything about units.'),
  ('welldata', 'beginner', 'final', null, 15, 'A LAS file records depth in feet with a constant 2 ft step. What is the step in metres?', '["0.6000 m","0.6562 m","0.6096 m","0.3048 m"]'::jsonb, 2, '1 ft = 0.3048 m exactly, so 2 ft = 0.6096 m. feet_20 converts to exactly this step, and the capstone grades it to 0.001 m.'),
  ('welldata', 'beginner', 'final', null, 16, 'feet_20 starts at 4900 ft. What is that depth in metres?', '["1470.00 m","1493.52 m","1633.33 m","1489.20 m"]'::jsonb, 1, '4900 x 0.3048 = 1493.52 m. The whole range 4900-5200 ft becomes 1493.52-1584.96 m.'),
  ('welldata', 'beginner', 'final', null, 17, 'An importer lazily converts a 2 ft step as 0.6 m instead of 0.6096 m. Over the 150 intervals of a 4900-5200 ft log, how far has the bottom sample drifted?', '["About 0.01 m, negligible","About 14.4 m","About 1.44 m","Nothing, rounding cancels out over many steps"]'::jsonb, 2, 'The per-step error is 0.0096 m and it accumulates: 0.0096 x 150 = 1.44 m of depth error at total depth. Unit constants are exact for a reason.'),
  ('welldata', 'beginner', 'final', null, 18, 'irregular_20''s header declares STEP 0. What does a zero STEP conventionally signal in LAS?', '["The file is corrupt and should be rejected","Depth increases by zero, meaning a repeated section","The step must be read from the ~C section instead","The depth increment is not constant; the file is irregularly sampled"]'::jsonb, 3, 'STEP 0 is the LAS convention for irregular sampling. The honest header tells you up front that no single step value describes the file.'),
  ('welldata', 'beginner', 'final', null, 19, 'Across irregular_20 the average depth increment works out to exactly 0.5 m, yet the import pipeline reports no uniform step. Why is the average not good enough?', '["Uniformity requires every consecutive increment to match, and an average can be exactly 0.5 while individual increments vary","The average was computed over too few samples to be trusted","The pipeline only accepts steps that are whole numbers of centimetres","The average includes null depth samples that bias it"]'::jsonb, 0, 'The end-to-end average, (1560 - 1500) / 120, is exactly 0.5 m, but in between the increments wander. Resampling and cross-well math need every step equal, not equal on average.'),
  ('welldata', 'beginner', 'final', null, 20, 'Which curves in feet_20 need unit conversion during import to a metric workspace?', '["Only the depth curve","All five curves","The depth curve (feet to metres) and the sonic DT curve (microseconds per foot to per metre)","None, because LAS files are unit-agnostic"]'::jsonb, 2, 'Depth is in feet and DT is in US/F; both are converted (the pipeline reports 2 converted curves). GR, RHOB and NPHI already carry unit-independent or metric-compatible values.'),
  ('welldata', 'beginner', 'final', null, 21, 'Why do downstream applications insist on uniform, metric depth grids rather than accepting each file as-is?', '["Because samples must align across curves and across wells for any arithmetic between them to be meaningful","Because metres compress better in the database","Because the LAS standard forbids feet in modern files","Because charts can only render uniform axes"]'::jsonb, 0, 'Curve-to-curve and well-to-well operations pair samples by depth. Mixed units or wandering steps silently misalign those pairings, so the importer normalises once, at the door.'),
  ('welldata', 'beginner', 'final', null, 22, 'nullheavy_20 declares NULL as -9999 rather than the common -999.25. What happens inside an importer that hard-codes -999.25?', '["The file is rejected with a clear error","Every -9999 is treated as a real measurement: null counts read zero and the statistics are poisoned by huge negative values","The parser substitutes the correct flag automatically from context","Only the depth column is affected"]'::jsonb, 1, 'The NULL flag is declared per file in ~W and must be read, not assumed. Treating -9999 as data drags means to absurd values and hides the fact that anything is missing.'),
  ('welldata', 'beginner', 'final', null, 23, 'A GR curve has 301 samples, 8 of them null flagged as -999.25, and a finite-sample mean of 64.93 GAPI. If the importer wrongly included the null flags as values, roughly what mean would it report?', '["About 36.6 GAPI","About 64.9 GAPI","About 72.9 GAPI","About -999 GAPI"]'::jsonb, 0, '(293 x 64.9272 + 8 x (-999.25)) / 301 is about 36.6. Eight flags out of 301 samples nearly halve the apparent mean, which is why statistics are computed over finite samples only.'),
  ('welldata', 'beginner', 'final', null, 24, 'In nullheavy_20 the NPHI curve carries 201 nulls out of 201 samples. What is this called and what is the correct response?', '["An offset curve; shift it to align with GR","A sparse curve; interpolate the gaps before use","A dead curve; flag it as carrying no data and never invent values for it","A miscalibrated curve; rescale it against RHOB"]'::jsonb, 2, 'A curve that is 100 percent null is dead: the mnemonic exists but no measurement does. It must be reported as dead, not filled, smoothed or guessed at.'),
  ('welldata', 'beginner', 'final', null, 25, 'A curve has 201 samples and 71 nulls. Over how many samples is its mean computed?', '["201","71","272","130"]'::jsonb, 3, 'Statistics run over finite samples only: 201 - 71 = 130. The null flags are markers of absence, not numbers.'),
  ('welldata', 'beginner', 'final', null, 26, 'What do a curve''s first-finite and last-finite depths tell you that the file''s depth range does not?', '["The interval over which that curve actually carries data, which can be much shorter than the file''s full range","The depths at which the tool was calibrated","The interval the service company certified","Nothing; they always equal the file''s start and stop"]'::jsonb, 0, 'A file spanning 1500-1650 m can hold a curve that only reads from 1520 m. Coverage is per curve, and the QC panel reports it per curve for exactly that reason.'),
  ('welldata', 'beginner', 'final', null, 27, 'In basic_20, which curves are complete, with zero null samples?', '["GR and RHOB","NPHI and DT","GR and DT","All four measurement curves"]'::jsonb, 1, 'NPHI and DT are complete; GR carries 8 nulls and RHOB 9. Even a clean file rarely has every curve complete, which is why null counts are checked per curve.'),
  ('welldata', 'beginner', 'final', null, 28, 'Why is a NULL flag value like -999.25 used at all, instead of simply leaving the field blank?', '["Blank fields are illegal in LAS","The flag doubles as an error code from the logging tool","It compresses better than whitespace","Columnar numeric formats need a parseable number in every position, so absence is encoded as an agreed impossible value"]'::jsonb, 3, 'The ~A block is fixed columns of numbers. A sentinel value keeps every row parseable while still encoding absence, provided every consumer honours the declared flag.'),
  ('welldata', 'beginner', 'final', null, 29, 'Which entries belong to the LAS well information section that the QC panel surfaces?', '["WELL, COMP, FLD, LOC, SRVC, DATE, STRT, STOP, STEP and NULL","Only STRT, STOP and STEP","The curve mnemonics and their units","The tool serial numbers and run tickets"]'::jsonb, 0, 'The ~W section carries the well''s identity (name, company, field, location, service, date) and the file''s depth frame (start, stop, step) plus the NULL flag.'),
  ('welldata', 'beginner', 'final', null, 30, 'quirks_20 carries a well name but almost no other identity entries (no company, field or location). What is the correct registry response?', '["Guess the field from the file name and proceed","Chase the missing metadata from the source before the well is relied on, and record what is unverified","Reject the file, since identity entries are mandatory","Copy identity entries from another well in the same folder"]'::jsonb, 1, 'Missing identity is a data-management problem to resolve, not to improvise. The data may parse perfectly while the well remains poorly identified; both facts belong in the registry.'),
  ('welldata', 'beginner', 'final', null, 31, 'The header declares STRT, STOP and STEP, and the parser also computes the same quantities from the actual depth column. When they disagree, which wins?', '["The header, because it is the official record","Neither; the file must be discarded","The values recomputed from the data, with the disagreement flagged","Whichever gives the rounder numbers"]'::jsonb, 2, 'Headers are claims; the data column is evidence. Trust-but-verify means recomputing the frame from the samples and flagging any header that disagrees.'),
  ('welldata', 'beginner', 'final', null, 32, 'A file''s header declares STEP 0.5 but the depth column shows wandering increments. What has the QC actually established?', '["The data is irregular regardless of the header''s claim, and downstream resampling decisions must be based on the data","The header is right and the data column has typos","The step is 0.5 on average so the file may be treated as uniform","The file uses feet and the header uses metres"]'::jsonb, 0, 'The declared step is only a claim. irregular_20 is the honest version (STEP 0); a file claiming 0.5 over irregular data is the dishonest version of the same hazard.'),
  ('welldata', 'beginner', 'final', null, 33, 'Why is well metadata treated as identity, on a par with the curve data itself?', '["Because the registry sorts wells alphabetically by company","Because metadata compresses the file index","Because interpreters read the header before the curves","Because perfectly parsed curves attached to the wrong well identity are worse than no data at all"]'::jsonb, 3, 'Attribution is everything: a flawless GR curve filed under the wrong well silently corrupts every map and correlation that touches it.'),
  ('welldata', 'beginner', 'final', null, 34, 'What QC value do the DATE and SRVC header entries add?', '["They set the depth reference datum","Provenance: when the data was produced and by whom, which anchors any later dispute about vintage or processing","They control the parser''s unit conversion","They are purely decorative fields"]'::jsonb, 1, 'Provenance entries let you answer ''which vintage is this, and whose processing'' years later. They cost nothing at import time and are nearly irrecoverable afterwards.'),
  ('welldata', 'beginner', 'final', null, 35, 'The registry already holds a well named KETA G1-1, and a new file arrives whose header also says WELL KETA G1-1 but with a different field and company. What should happen?', '["The file is merged into the existing well automatically since names match","The new file silently replaces the older well","The name is ignored and a new anonymous well is created","The conflict is surfaced for a human decision before anything is attached to the existing well"]'::jsonb, 3, 'Same name plus conflicting identity is exactly the trap automation must not resolve silently. The data manager resolves whether it is the same well, a sidetrack, or a naming collision.'),
  ('welldata', 'beginner', 'final', null, 36, 'In the import QC checklist, which checks must be completed before any curve statistics are worth reading?', '["Company and field spelling","Cross-plots against offset wells","Parsing (version and wrap), the depth frame (units, range, step) and the NULL flag","Nothing; statistics are independent of the rest"]'::jsonb, 2, 'Statistics computed on a misparsed file, a misconverted depth column or an unhonoured NULL flag are confidently wrong. Structure first, numbers second.'),
  ('welldata', 'beginner', 'final', null, 37, 'Which six quantities does the Well Data Manager Associate capstone grade?', '["basic_20 depth samples, basic_20 GR nulls, basic_20 mean GR, feet_20 converted step, nullheavy_20 NPHI nulls, wrapped_12 depth samples","Six mean values, one per curve of basic_20 plus depth","The STRT, STOP and STEP of two files","The null counts of all curves in all six files"]'::jsonb, 0, 'Six numbers, each requiring one file loaded and one QC fact read correctly: 301 samples, 8 GR nulls, mean GR 64.93, step 0.6096 m, 201 NPHI nulls, 161 samples.'),
  ('welldata', 'beginner', 'final', null, 38, 'On the deep path, when does the graded capstone unlock?', '["As soon as the first module quiz is passed","Immediately on enrollment","After any three module quizzes","After every module quiz is passed and the final exam is passed"]'::jsonb, 3, 'The deep path is lessons, then each module''s quiz (75 percent), then the final exam (70 percent), and only then the capstone. The server enforces the order.'),
  ('welldata', 'beginner', 'final', null, 39, 'What happens after three consecutive failures of a module quiz?', '["A 24-hour cooldown before the next attempt","The course resets to module one","The quiz is waived and the module marked complete","The enrollment is cancelled"]'::jsonb, 0, 'Three fails trigger a 24-hour cooldown. The bank is large and attempts are pinned, so the path to passing is rereading the lessons, not resampling questions.'),
  ('welldata', 'beginner', 'final', null, 40, 'Where on the QC panel do you read the number of null samples in a specific curve, such as GR?', '["In the well header table","In that curve''s row of the curve table, in the nulls column","In the depth tiles at the top","It must be computed by hand from the raw text"]'::jsonb, 1, 'The curve table reports per-curve samples, nulls, first and last finite depths, and finite-sample mean. Reading the right row is the whole skill the capstone tests.'),
  ('welldata', 'beginner', 'final', null, 41, 'What does the Professional tier add on top of the Associate QC skills?', '["Manual editing of curve values","Writing LAS files back to disk","The full SI import pipeline: automatic unit conversion and curve-kind recognition, read from the import panel","Seismic tie quality control"]'::jsonb, 2, 'The Professional capstone runs feet_20 through the full pipeline: converted start, stop and step, how many curves needed conversion, and how many curve kinds were recognised.'),
  ('welldata', 'beginner', 'final', null, 42, 'Besides the certificate itself, what does passing the Well Data Manager Associate capstone unlock?', '["A discount on the Professional tier","Automatic enrollment in all other courses","Nothing beyond the certificate","Enrollment eligibility for the other geoscience courses, since this course is their prerequisite root"]'::jsonb, 3, 'welldata is the prereq root: a live Associate certification here is what the enrollment trigger checks before admitting you to the other five geoscience courses.');
